    padding: 12px 20px;
    background: #667eea;
    color: white;
    border: none;
    border-radius: 8px;
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.3s;
}

button:hover {
    background: #5568d3;
}

.btn-secondary {
    background: #6c757d;
}

.btn-secondary:hover {
    background: #5a6268;
}

.btn-danger {
    background: #dc3545;
    padding: 8px 15px;
    font-size: 14px;
}

.btn-danger:hover {
    background: #c82333;
}

.btn-success {
    background: #28a745;
    padding: 8px 15px;
    font-size: 14px;
}

.btn-success:hover {
    background: #218838;
}

.link-registro {
    text-align: center;
    margin-top: 15px;
    color: #666;
